<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\ActivityLog;use App\Models\Company;use App\Models\Job;use App\Models\JobApplication;use App\Models\PaymentOrder;use App\Models\User;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ReportController extends Controller{
public function admin(Request $r):JsonResponse{abort_unless($r->user()->is_admin,403);$applications=JobApplication::select('status',DB::raw('count(*) as total'))->groupBy('status')->pluck('total','status');$views=DB::table('job_engagement_events')->where('event','view')->count();$starts=DB::table('job_engagement_events')->where('event','apply_start')->count();$applied=JobApplication::count();return response()->json(['data'=>['summary'=>['users'=>User::count(),'candidates'=>User::where('account_type','candidate')->count(),'companies'=>Company::count(),'verified_companies'=>Company::where('verification_status','verified')->count(),'active_jobs'=>Job::where('status','active')->count(),'job_views'=>$views,'apply_starts'=>$starts,'applications'=>$applied,'view_to_application_rate'=>$views?round($applied/$views*100,1):0,'approved_revenue'=>(float)PaymentOrder::where('status','approved')->sum('amount')],'applications_by_status'=>$applications,'recent_activity'=>ActivityLog::with('user:id,name,email')->latest()->limit(30)->get()]]);}
public function company(Request $r):JsonResponse{abort_unless($r->user()->account_type==='company',403);$company=$r->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422);$jobs=$company->jobs();$jobIds=(clone$jobs)->pluck('id');$applications=JobApplication::whereIn('job_id',$jobIds);$views=DB::table('job_engagement_events')->whereIn('job_id',$jobIds)->where('event','view')->count();$starts=DB::table('job_engagement_events')->whereIn('job_id',$jobIds)->where('event','apply_start')->count();$applied=$applications->count();$items=$company->jobs()->withCount('applications')->latest()->get(['id','title','status','published_at'])->map(function($job){$counts=DB::table('job_engagement_events')->where('job_id',$job->id)->select('event',DB::raw('count(*) total'))->groupBy('event')->pluck('total','event');$job->views_count=(int)($counts['view']??0);$job->apply_starts_count=(int)($counts['apply_start']??0);$job->conversion_rate=$job->views_count?round($job->applications_count/$job->views_count*100,1):0;return$job;});return response()->json(['data'=>['summary'=>['jobs'=>$jobs->count(),'active_jobs'=>(clone$jobs)->where('status','active')->count(),'job_views'=>$views,'apply_starts'=>$starts,'applications'=>$applied,'conversion_rate'=>$views?round($applied/$views*100,1):0,'interviews'=>(clone$applications)->where('status','interview')->count(),'hired'=>(clone$applications)->where('status','hired')->count()],'applications_by_status'=>$applications->select('status',DB::raw('count(*) as total'))->groupBy('status')->pluck('total','status'),'jobs'=>$items]]);}}
